16	 *  slot 'a'|'b'|'c'  -> markdown.markdown(text)                       (no extensions)
17	 *  slot 'd'          -> extensions=['extra','tables']
18	 *  slot 'e'          -> extensions=['codehilite','fenced_code']
19	 *  slot 'f'          -> extensions=['toc']
20	 *  slot '5'          -> phase5: all 5 extensions + output_format='xhtml'
21	 *                       (text goes in --f so it is the tail of the concatenated doc)
22	 */
23	export function phase(slot, s) {
24	  if (slot === '5') return phase5(s);
25	  const args = { ...MK }; args[slot] = s;
26	  const out = run(args);
27	  const lines = out.split('\n');
28	  const pos = ORDER.indexOf(slot);
29	  let start = 0;
30	  for (let k = 0; k < pos; k++) start = lines.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
31	  const end = pos < 5 ? lines.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start)
32	                      : lines.indexOf('<h1>Combined Document</h1>', start);
33	  return lines.slice(start, end).join('\n');
34	}
35	
36	/** phase5 of a document whose last arg is `s`; returns only the tail after the 5 marker paragraphs. */
37	export function phase5(s) {
38	  const args = { ...MK }; args.f = s;
39	  const out = run(args);
40	  const lines = out.split('\n');
