import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
export const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];

export function runRaw(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k, args[k] === undefined ? MK[k] : args[k]);
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { status: r.status, out: r.stdout, err: r.stderr };
}

/**
 * Split full stdout into the 9 printed phases.
 * Requires: phase3 starts with the line '<h1>Combined Document</h1>' and
 * phase4 starts with a line beginning '<article>' and ends at the first
 * subsequent line ending with '</article>'.
 * Returns {p1a,p1b,p1c,p2d,p2e,p2f,p3,p4,p5, lines}
 */
export function split(out) {
  const lines = out.split('\n');
  if (lines[lines.length - 1] !== '') throw new Error('no trailing newline!');
  lines.pop();
  const i3 = lines.indexOf('<h1>Combined Document</h1>');
  if (i3 < 0) throw new Error('no phase3 marker');
  let i4 = -1;
  for (let i = i3 + 1; i < lines.length; i++) if (lines[i].startsWith('<article>')) { i4 = i; break; }
  if (i4 < 0) throw new Error('no phase4 marker');
  let i5 = -1;
  for (let i = i4; i < lines.length; i++) if (lines[i].endsWith('</article>')) { i5 = i + 1; break; }
  if (i5 < 0) throw new Error('no article end');
  const head = lines.slice(0, i3);            // the 6 phase1/2 outputs, each may be multiline
  return {
    head: head.join('\n'),
    p3: lines.slice(i3, i4).join('\n'),
    p4: lines.slice(i4, i5).join('\n'),
    p5: lines.slice(i5).join('\n'),
  };
}

/** Vary exactly one slot; markers elsewhere. Returns split + the isolated phase for that slot. */
export function one(slot, text) {
  const args = { ...MK }; args[slot] = text;
  const r = runRaw(args);
  if (r.status !== 0) return { status: r.status, err: r.err };
  const s = split(r.out);
  // isolate the varied slot's own printed phase out of head
  const hl = s.head.split('\n');
  const pos = ORDER.indexOf(slot);
  let start = 0;
  for (let k = 0; k < pos; k++) start = hl.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
  let end;
  if (pos < 5) end = hl.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start);
  else end = hl.length;
  s.own = hl.slice(start, end).join('\n');
  s.status = 0;
  return s;
}
