import { runRaw, MK } from './h.mjs';

const ORDER = ['a','b','c','d','e','f'];
const NAMES = { a:'A', b:'B', c:'C', d:'D', e:'E', f:'F' };

/** Given the full stdout, peel the 6 leading phases by matching against a candidate phase3. */
function analyse(args) {
  const r = runRaw(args);
  const out = r.out;
  // find phase3 start = first line '<h1>Combined Document</h1>' that begins a line
  const i3 = out.indexOf('\n<h1>Combined Document</h1>\n');
  const head = out.slice(0, i3 + 1);            // includes trailing \n
  const rest = out.slice(i3 + 1);
  // phase 4 candidate: '<article>' + p3 + '</article>' ; find that
  // p3 ends where '\n<article><h1>Combined Document</h1>\n' starts
  const i4 = rest.indexOf('\n<article><h1>Combined Document</h1>\n');
  let p3 = null, p4 = null, p5 = null;
  if (i4 >= 0) {
    p3 = rest.slice(0, i4);
    const rest2 = rest.slice(i4 + 1);
    const expect4 = '<article>' + p3 + '</article>';
    if (rest2.startsWith(expect4 + '\n')) {
      p4 = expect4;
      p5 = rest2.slice(expect4.length + 1);
      if (p5.endsWith('\n')) p5 = p5.slice(0, -1);
    }
  }
  // peel head into 6 phases using known marker slots
  const phases = {};
  let h = head;
  for (const k of ORDER) {
    const v = args[k] === undefined ? MK[k] : args[k];
    // marker slots produce '<p>MKxx</p>\n'
    if (args[k] === undefined) { const t = '<p>' + MK[k] + '</p>\n'; if (h.startsWith(t)) { phases[k] = '<p>'+MK[k]+'</p>'; h = h.slice(t.length); continue; } }
    phases[k] = null;
  }
  return { status: r.status, out, head, p3, p4, p5, phases, p4ok: p4 !== null };
}

/** Build expected phase3 from the 6 rendered contents, using the hypothesised rule. */
function expectP3(contents) {
  let s = '<h1>Combined Document</h1>\n';
  const parts = [];
  for (let i = 0; i < 6; i++) {
    const c = contents[i];
    parts.push('<h2>Section ' + 'ABCDEF'[i] + '</h2>\n' + (c === '' ? '' : c + '\n\n'));
  }
  s += parts.join('');
  return s.replace(/\s+$/, '');
}

// ---- invariant test over many inputs: vary one slot at a time and check p4 == <article>+p3+</article>
const varied = [
  '', 'x', 'x\n\ny', '# H', '## H', '> q', '- a\n- b', '    code', '<div>d</div>',
  '<div>\nd\n</div>', '<p>p</p>', '<!-- c -->', '<hr>', '<br>', '<span>s</span>',
  '| a | b |\n| - | - |\n| 1 | 2 |', '```\nc\n```', '```py\nprint(1)\n```',
  'x\n\n</div>', '</div>\n\nx', '</p>', '</b>', '<b>bold</b>', '<em>e</em>',
  '<h1>raw h1</h1>', '<h9>bogus</h9>', '<foo>bar</foo>', '<foo/>',
  '![i](u)', '[l](u)', '`c`', 'a & b', '<a href="#">l</a>',
  'text\n\n<div>d</div>\n\nmore', '<div>1</div>\n<div>2</div>',
  '示例 文本', 'é́', 'tab\there', 'x\ry', 'x\r\ny', 'x\fy', 'x\n', '   ',
  '\\## y', 'z\n\\## y', '[TOC]', '*[X]: y', 'Term\n\n:   D', 'n[^1]\n\n[^1]: f',
];
let bad = 0;
for (const slot of ORDER) {
  for (const v of varied) {
    const a = analyse({ [slot]: v });
    if (a.status !== 0) { console.log('NONZERO', slot, JSON.stringify(v), a.status); bad++; continue; }
    if (!a.p4ok) { console.log('P4-MISMATCH', slot, JSON.stringify(v), JSON.stringify(a.out)); bad++; }
  }
}
console.log('### p4 invariant violations: ' + bad);

import { runRaw, MK } from './h.mjs';
const ORDER = ['a','b','c','d','e','f'];

function analyse(slot, v) {
  const args = { [slot]: v };
  const r = runRaw(args);
  const out = r.out;
  const i3 = out.indexOf('\n<h1>Combined Document</h1>\n');
  const head = out.slice(0, i3 + 1);
  const rest = out.slice(i3 + 1);
  const i4 = rest.indexOf('\n<article><h1>Combined Document</h1>\n');
  const p3 = rest.slice(0, i4);
  const p4 = '<article>' + p3 + '</article>';
  let p5 = rest.slice(i4 + 1 + p4.length + 1);
  if (p5.endsWith('\n')) p5 = p5.slice(0, -1);
  const pos = ORDER.indexOf(slot);
  let pre = 0; for (let k = 0; k < pos; k++) pre += ('<p>' + MK[ORDER[k]] + '</p>\n').length;
  let suf = 0; for (let k = pos + 1; k < 6; k++) suf += ('<p>' + MK[ORDER[k]] + '</p>\n').length;
  const own = head.slice(pre, head.length - suf - 1);
  const contents = ORDER.map(k => k === slot ? own : '<p>' + MK[k] + '</p>');
  // expected p3 with SEP='\n\n'
  let exp = '<h1>Combined Document</h1>\n';
  for (let i = 0; i < 6; i++) {
    const c = contents[i];
    exp += '<h2>Section ' + 'ABCDEF'[i] + '</h2>\n' + (c === '' ? '' : c + '\n\n');
  }
  exp = exp.replace(/\n+$/, '');
  return { own, p3, p5, exp, match: exp === p3, out };
}

const varied = [
