  '> q', '- a\n- b', '1. a\n2. b', '    code', '\tcode',
  '<div>d</div>', '<div>\nd\n</div>', '<p>p</p>', '<!-- c -->', '<hr>', '<hr/>', '<br>',
  '<span>s</span>', '<b>bold</b>', '<em>e</em>', '<h1>raw h1</h1>', '<h9>bogus</h9>',
  '<foo>bar</foo>', '<foo/>', '<foo>', '</p>', '</b>', '</div>', '</span>',
